];

export interface ComparisonRow {
  label: string;
  tooltip: string;
  starter: string | boolean;
  growth: string | boolean;
  pro: string | boolean;
}

export const COMPARISON_TABLE: ComparisonRow[] = [
  {
    label: "Monthly delivery capacity",
