.newPriceSec {
  background-color: #fff;
  margin-bottom: 0;
  padding: 80px 5% 20px;
  display: block;
  position: relative;
}

/* Pricing page variant: transparent bg + 4rem top padding */
.newPriceSecPage {
  background-color: transparent;
  padding-top: 4rem;
}

.containerLarge3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

.priceTitleGrid {
  display: grid;
  grid-column-gap: 24px;
  grid-row-gap: 24px;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  place-items: center;
  margin-bottom: 20px;
}

.maxWidthSmall4 {
  width: 100%;
  max-width: 550px;
}

.priceSubheadOut {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: center;
  align-items: center;
  display: flex;
}

.pricesubott {
  background-color: #21cfff12;
  border: 1px solid #05bafe;
  border-radius: 20px;
  margin-bottom: 17px;
  padding: 0 13px;
  line-height: 14px;
}

.faqSkyText {
  color: #21cfff;
  text-transform: capitalize;
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  font-weight: 500;
}

.heading2 {
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 40px;
  text-align: center;
  line-height: 45px;
  margin-top: 0;
  margin-bottom: 20px;
}

.paragraph {
  color: #000;
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  margin-bottom: 0;
}

/* Tabs menu */
.pricingTabsMenuLarge {
  grid-column-gap: 6px;
  grid-row-gap: 6px;
  background-color: #f4f7fa;
  border-style: none;
  border-color: #cdebfa;
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 24px;
  padding: 5px 7px;
  display: flex;
}

.pricingTabLink {
  grid-column-gap: 8px;

          >
            <div className={styles["priceTabText"]}>Quarterly</div>
            <div className={styles["pricingBadge"]}>Save 10%</div>
          </button>
          <button
            className={`${styles["pricingTabLink"]} ${period === "annually" ? styles["pricingTabLinkActive"] : ""}`}
            onClick={() => setPeriod("annually")}
          >
            <div className={styles["priceTabText"]}>Annually</div>
            <div className={styles["pricingBadge"]}>Save 20%</div>
          </button>
        </div>

        {/* Plan cards */}
        <div className={styles["pricingGrid"]}>
          {PRICING_PLANS.map((plan) => {
            const price = getPlanPrice(plan, period);
            const link = getPlanCheckoutLink(plan, period);
            const isPopular = plan.popular;
            const isMonthly = period === "monthly";

            const cardClass = isPopular
              ? `${styles["pricingCard2"]} ${styles["pricingCard2CenterPcard"]}`
              : `${styles["pricingCard2"]} ${styles["pricingCard2WhiteCard"]}`;

            const btnClass = isPopular
              ? `${styles["buttonPricing"]} ${styles["buttonPricingSky"]}`
              : styles["buttonPricing"];

            const innerColClass = `${styles["columnXSmall10"]} ${styles["columnXSmall10CenterCol"]}`;

            return (
              <div key={plan.id} className={cardClass}>
                {isPopular && (
                  <div className={styles["pTopDv"]}>
                    <Image
                      src="/images/webflow/Layer_2.svg"
                      alt="flash icon"
                      width={18}
                      height={18}
                    />
                    <p className={styles["mostPopular"]}>Most Popular</p>
                  </div>
                )}

                <div className={innerColClass}>
                  <div className={styles["priceSubOtt"]}>
                    <h6 className={styles["h6Heading5PlanName"]}>{plan.name}</h6>
                  </div>
                  <div className={styles["priceBadgeOut"]}>
                    <h3 className={styles["h3Heading3"]}>
                      ${price.toLocaleString()}/month
                    </h3>
                    {!isMonthly && (
                      <p className={styles["comparePrice"]}>
                        ${plan.monthlyPrice.toLocaleString()}.00
                      </p>
                    )}
                  </div>
                  <p className={styles["paragraphSmall27TextColorTertiary"]}>
                    {plan.tagline}
                  </p>
                </div>

                <div>
                  <div className={styles["columnSmall5"]}>
                    <div className={styles["paragraphXSmall13TextColorTertiary"]}>
                      <strong>{plan.featuresLabels[period]}</strong>
