import { createMetadata } from "@/lib/seo/metadata";
import { GradientPageBg } from "@/components/shared/page-bg";
import { PricingSection } from "@/components/home/pricing-section";
import { CustomPlanCta } from "@/components/pricing/custom-plan-cta";
import { RoiCalculator } from "@/components/pricing/roi-calculator";
import { BetaCta } from "@/components/shared/beta-cta";

export const metadata = createMetadata({
  title: "White Label Web Development Pricing | Plans from $999/mo | Boldteq",
  description:
    "Transparent white-label web dev pricing for agencies. Starter $999/mo, Growth $1,999/mo, Pro $3,499/mo. No contracts, pause anytime. 14-day guarantee.",
  path: "/pricing",
});

const pricingSchema = {
  "@context": "https://schema.org",
  "@type": "Service",
  serviceType: "White Label Web Development",
  provider: { "@type": "Organization", name: "Boldteq" },
  hasOfferCatalog: {
    "@type": "OfferCatalog",
    itemListElement: [
      {
        "@type": "Offer",
        name: "Starter",
        price: "999",
        priceCurrency: "USD",
      },
      {
        "@type": "Offer",
        name: "Growth",
        price: "1999",
        priceCurrency: "USD",
      },
      {
        "@type": "Offer",
        name: "Pro",
        price: "3499",
        priceCurrency: "USD",
      },
    ],
  },
};

export default function PricingPage() {
  return (
    <>
      <GradientPageBg pricing={true} />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(pricingSchema) }}
      />
      <PricingSection transparent />
      <CustomPlanCta />
      <RoiCalculator />
      <BetaCta />
    </>
  );
}

