import { createMetadata } from "@/lib/seo/metadata";
import { PageHero } from "@/components/shared/page-hero";
import { NewsletterSignup } from "@/components/shared/newsletter-signup";
import { SectionWrapper } from "@/components/shared/section-wrapper";

export const metadata = createMetadata({
  title: "Newsletter | Boldteq",
  description:
    "Subscribe to agency growth insights delivered monthly. Smart growth strategies, CRM playbooks, and industry trends for modern agencies.",
  path: "/newsletter",
});

export default function NewsletterPage() {
  return (
    <>
      <PageHero
        title="Agency Growth Insights Delivered Monthly"
        subtitle="Smart growth strategies, CRM playbooks, industry trends, early product updates, and member-only offers — designed for modern agencies."
        badge="Newsletter"
      />
      <SectionWrapper className="text-center">
        <div style={{ maxWidth: "640px", margin: "0 auto" }}>
          <NewsletterSignup />
        </div>
      </SectionWrapper>
    </>
  );
}

