import styles from "./careers-testimonials.module.css";

const TESTIMONIALS = [
  {
    quote:
      "At Boldteq, quality isn\u2019t an afterthought \u2014 it\u2019s built into how we operate. Every task goes through structured review, and every team member takes ownership of the result.",
    name: "Arjun Mehta",
    role: "Head of Engineering",
  },
  {
    quote:
      "There\u2019s no ambiguity here. Everyone knows what\u2019s expected, how it\u2019s measured, and who\u2019s responsible. That clarity is what makes Boldteq different from anywhere else I\u2019ve worked.",
    name: "Sofia Rao",
    role: "Operations Lead",
  },
  {
    quote:
      "I\u2019ve never worked in a place where ownership is this deeply ingrained. When you\u2019re given a task, you own it end to end. That trust changes how you show up every day.",
    name: "Daniel Brooks",
    role: "Senior Developer",
  },
  {
    quote:
      "What sets Boldteq apart is how seriously we protect the client experience. We don\u2019t just deliver \u2014 we deliver in a way that makes agencies look incredible to their clients.",
    name: "Nisha Kapoor",
    role: "Client Success Manager",
  },
];

export function CareersTestimonials() {
  return (
    <section className={styles.section}>
      <div className={styles.container}>
        <div className={styles.header}>
          <div className={styles.badge}>
            <p className={styles.badgeText}>
              <strong>Voices from Boldteq</strong>
            </p>
          </div>
          <h2 className={styles.heading}>What Our Team Says</h2>
        </div>

        <div className={styles.grid}>
          {TESTIMONIALS.map((t) => (
            <div key={t.name} className={styles.card}>
              <p className={styles.quote}>&ldquo;{t.quote}&rdquo;</p>
              <div className={styles.author}>
                <p className={styles.authorName}>{t.name}</p>
                <p className={styles.authorRole}>{t.role}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

