file.content:
.section {
  background-color: #f5f7fa;
  padding: 80px 5%;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 48px;
}

.badge {
  display: inline-flex;
  background-color: #21cfff12;
  border: 1px solid #05bafe;
  border-radius: 20px;
  padding: 0 13px;
  margin-bottom: 17px;
}

.badgeText {
  color: transparent;
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: 32px;
  margin: 0;
}

.heading {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 45px;
  margin: 0;
}

.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.card {
  background-color: #fff;
  border-radius: 12px;
  padding: 32px;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.06);
}

.quote {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  font-style: italic;
  margin: 0 0 24px;
}

.author {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.authorName {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 700;
  margin: 0;
}

.authorRole {
  color: #6b7280;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  margin: 0;
}

@media screen and (max-width: 767px) {
  .grid {
    grid-template-columns: 1fr;
  }

  .heading {
    font-size: 28px;
    line-height: 36px;
  }
}

