/* ============================================================
   CAREERS TESTIMONIALS — careers-testimonials.module.css
   Extracted from boldteq-v1-0.webflow.css career-team-* classes
   ============================================================ */

.section {
  padding: 80px 5%;
  position: relative;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 40px;
}

.heading {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 45px;
  margin: 0 0 16px;
  text-align: center;
}

.subheading {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  max-width: 600px;
  margin: 0 auto;
}

/* career-team-grid — 2 column grid */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-column-gap: 24px;
  grid-row-gap: 24px;
  margin-top: 40px;
}

/* Large main card (Arjun Mehta) */
.mainCard {
  background-color: transparent;
  border-radius: 0;
  padding-top: 0;
}

.mainCardImage {
  background-color: transparent;
  border-radius: 15px;
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  margin-bottom: 20px;
}

.teamImage {
  object-fit: cover;
  border-radius: 15px;
}

.memberName {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 22px;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 4px;
}

.memberNameSide {
  color: #082753;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
  margin: 0 0 4px;
}

.memberRole {
  color: #05bafe;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 500;
  margin: 0 0 12px;
}

.mainQuote {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  text-align: left;
  margin: 0 0 20px;
}

.continueBtn {
  color: #fff;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  display: inline-flex;
  align-items: center;
  padding: 0.6rem 2.5rem 0.6rem 1rem;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
  transition: opacity 0.2s;
}

.continueBtn:hover {
  opacity: 0.9;
}

/* Right column — 3 smaller cards */
.sideColumn {
  display: flex;
  flex-flow: column;
  gap: 16px;
}

/* Each smaller card: grid with image + text */
.sideCard {
  display: grid;
  grid-template-columns: 0.65fr 1.35fr;
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  place-items: center stretch;
  background-color: transparent;
  border-radius: 0;
  padding-top: 0;
}

.sideCardImage {
  background-color: transparent;
  border-radius: 15px;
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  overflow: hidden;
}

.sideCardText {
  display: flex;
  flex-flow: column;
  gap: 4px;
}

.sideQuote {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  line-height: 22px;
  text-align: left;
  margin: 0;
}

/* ─── Responsive ───────────────────────────────────────────── */

@media screen and (max-width: 991px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 767px) {
  .heading {
    font-size: 28px;
    line-height: 36px;
  }

  .sideCard {
    grid-template-columns: 1fr;
  }

  .sideCardImage {
    aspect-ratio: 16 / 9;
  }
}

