/* ─── Footer CSS Module ───────────────────────────────────────────────────────
   Extracted verbatim from boldteq-v1-0.webflow.css
   ─────────────────────────────────────────────────────────────────────────── */

/* ─── Outer footer section ───────────────────────────────────────────────────── */

.footer {
  background-color: #082753;
  padding: 72px 5% 16px;
  position: relative;
}

/* ─── Container ──────────────────────────────────────────────────────────────── */

.container-large-6 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* ─── Outer column ───────────────────────────────────────────────────────────── */

.column-x-large {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex-direction: column;
  display: flex;
}

/* ─── Two-column grid (newsletter | links) ───────────────────────────────────── */

.footer-grid {
  grid-column-gap: 3rem;
