/*
  Matches Webflow .blue-sec + .book-section.remove-pattern
  - Centered layout (default): used on blog, how-it-works, scope, testimonials
  - Left-aligned layout (align="left"): used on beta page with bullets
*/
export function CtaBanner({
  title = "Ready to Deliver This Level of Work Under Your Brand?",
  subtitle = "Partner with Boldteq as your dedicated backend delivery team and gain a reliable, scalable foundation for your technology initiatives.",
  primaryCta = { label: "Book a Demo", href: "/book-a-demo" },
  secondaryCta,
  bullets,
  align = "center",
}: {
  title?: string;
  subtitle?: string;
  primaryCta?: { label: string; href: string };
  secondaryCta?: { label: string; href: string };
  bullets?: string[];
  align?: "center" | "left";
}) {
  const isLeft = align === "left";

  return (
    <section
      style={{
        backgroundColor: "transparent",
        marginBottom: "70px",
        padding: "0 5%",
        position: "relative",
      }}
    >
      <div
        style={{
          backgroundColor: "#082753",
          backgroundImage: "url('/images/webflow/Union.svg')",
          backgroundPosition: "100% 100%",
          backgroundRepeat: "no-repeat",
          backgroundSize: "auto",
          borderRadius: "20px",
          padding: "40px 20px 50px",
          maxWidth: "1280px",
          margin: "0 auto",
          textAlign: isLeft ? "left" : "center",
        }}
      >
        <div
          style={{
            maxWidth: isLeft ? "700px" : undefined,
          }}
        >
          <h2
            style={{
              color: "#ffffff",
              fontFamily: "'Roobert PRO', Arial, sans-serif",
              fontSize: "40px",
              fontWeight: 700,
              lineHeight: "45px",
              margin: "0",
            }}
          >
            {title}
          </h2>

          {subtitle && (
            <p
              style={{
                color: "rgba(255, 255, 255, 0.7)",
                fontFamily: "'Roobert PRO', Arial, sans-serif",
                fontSize: "16px",
                lineHeight: "28px",
                marginTop: "16px",
                maxWidth: isLeft ? undefined : "600px",
                marginLeft: isLeft ? undefined : "auto",
                marginRight: isLeft ? undefined : "auto",
              }}
            >
              {subtitle}
            </p>
          )}

          {/* Bullet list (beta page) */}
          {bullets && bullets.length > 0 && (
            <div
              style={{
                display: "flex",
                flexWrap: "wrap",
                gap: "8px 24px",
                marginTop: "20px",
              }}
            >
              {bullets.map((bullet) => (
                <div
                  key={bullet}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "6px",
                    color: "#fff",
                    marginBottom: "2px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      flexShrink: 0,
                    }}
                  >
                    <Image
                      src="/images/webflow/Group-1.svg"
                      alt="Check Icon"
                      width={14}
                      height={14}
                    />
                  </div>
                  <p
                    style={{
                      color: "#fff",
                      fontFamily: "'Roobert PRO', Arial, sans-serif",
                      fontSize: "16px",
                      lineHeight: "28px",
                      margin: 0,
                    }}
                  >
                    {bullet}
                  </p>
                </div>
              ))}
            </div>
          )}

          <div
            style={{
              display: "flex",
              justifyContent: isLeft ? "flex-start" : "center",
              alignItems: "center",
              gap: "20px",
              marginTop: "32px",
              flexWrap: "wrap",
            }}
          >
            <Link
              href={primaryCta.href}
              style={{
                color: "#fff",
                fontFamily: "'Roobert PRO', Arial, sans-serif",
                fontSize: "1rem",
                fontWeight: 700,
                lineHeight: "1.75rem",
                textDecoration: "none",
                backgroundImage: isLeft
                  ? "linear-gradient(90deg, #21cfff, #019ae6)"
                  : "url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6)",
                backgroundPosition: isLeft ? undefined : "93%, 0 0",
                backgroundRepeat: "no-repeat, repeat",
                backgroundSize: "auto, auto",
                border: "2px solid transparent",
                borderRadius: "0.75rem",
                padding: "0.75rem 1.25rem",
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              {primaryCta.label}
            </Link>

            {secondaryCta && (
              <Link
                href={secondaryCta.href}
                style={{
                  color: "#019ae6",
                  fontFamily: "'Roobert PRO', Arial, sans-serif",
                  fontSize: "1rem",
                  fontWeight: 700,
                  lineHeight: "1.75rem",
                  textDecoration: "none",
                  backgroundColor: "#fff",
                  backgroundImage:
                    "url('/images/webflow/Group-46729-1.svg')",
                  backgroundPosition: "94%",
                  backgroundRepeat: "no-repeat",
                  backgroundSize: "auto",
                  borderRadius: "0.75rem",
                  padding: "0.75rem 3rem 0.75rem 1.25rem",
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                {secondaryCta.label}
              </Link>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

