import { notFound } from "next/navigation";
import { PORTFOLIO_DETAILS } from "@/lib/constants/portfolio-details";
import { createMetadata } from "@/lib/seo/metadata";
import { CaseStudyContent } from "@/components/our-works-detail/case-study-content";
import { CaseStudyGallery } from "@/components/our-works-detail/case-study-gallery";
import layoutStyles from "./case-study-layout.module.css";

export function generateStaticParams() {
  return PORTFOLIO_DETAILS.map((d) => ({ slug: d.slug }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
  if (!detail) return {};
  return createMetadata({
    title: `${detail.title} | Case Study | Boldteq`,
    description: `${detail.challenge.slice(0, 155)}...`,
    path: `/our-works/${detail.slug}`,
    ogImage: detail.gallery[0],
  });
}

export default async function CaseStudyPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
  if (!detail) notFound();

  return (
    <section className={layoutStyles.pageOut}>
      <div className={layoutStyles.container}>
        <div className={layoutStyles.grid}>
          <CaseStudyContent detail={detail} />
          <CaseStudyGallery images={detail.gallery} title={detail.title} />
        </div>
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import styles from "./newsletter-signup.module.css";

export function NewsletterSignup() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!email) return;
    // TODO: integrate with email service
    setStatus("success");
    setEmail("");
  }

  return (
    <div className={styles["footerNewsletterCard"]}>
      <div className={styles["footerNewsletterTitle"]}>
        <div className={styles["newsSubheadOut"]}>
          <div className={styles["newsubott"]}>
            <Image
              src="/images/webflow/Layer_1-57.svg"
              alt="sparkle icon"
              width={18}
              height={18}
            />
            <p style={{ margin: 0, fontSize: "12px", lineHeight: "32px" }}>
              <strong className={styles["faqSkyText"]}>
                Join 500+ Subscribers
              </strong>
              <br />
            </p>
          </div>
        </div>
        <div className={styles["newsHeading"]}>
          Agency Growth Insights{" "}
          <span className={styles["gradientSpan"]}>
            <br />
            Delivered Monthly
          </span>
        </div>
        <p className={styles["paragraphSmall4TextColorGray600"]}>
          Smart growth strategies, CRM playbooks, industry trends, early product
          updates, and member-only offers — designed for modern agencies.
        </p>
      </div>

      <div className={styles["footerNewsletterFormBlock"]}>
        {status === "success" ? (
          <div className={styles["successMessage"]}>
            <div>Thank you! Your submission has been received!</div>
          </div>
        ) : (
          <form
            id="wf-form-Contact-Form"
            name="wf-form-Contact-Form"
            onSubmit={handleSubmit}
            className={styles["columnLargeRowGap0"]}
          >
            <div className={styles["columnLarge"]}>
              <div className={styles["columnTiny2"]}>
                <input
                  className={styles["textFieldSmall"]}
                  maxLength={256}
                  name="Email-Footer-Newsletter"
                  placeholder="Enter your email"
                  type="email"
                  id="Email-Footer-Newsletter"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
                <button
                  type="submit"
                  className={styles["buttonSecondarySmall"]}
                >
                  Get Started
                </button>
              </div>
            </div>
          </form>
        )}
        {status === "error" && (
          <div className={styles["errorMessage"]}>
            <div>Oops! Something went wrong while submitting the form.</div>
          </div>
        )}
      </div>

      <div className={styles["newsletterBtmLine"]}>
        <Image
          src="/images/webflow/Vector-24.svg"
          alt="verified icon"
          width={16}
          height={16}
          className={styles["shieldIcon"]}
        />
        <p className={styles["newsBtmPara"]}>
          100% privacy guaranteed. Unsubscribe anytime.
        </p>
      </div>
    </div>
  );
}

