   Live site: container 1300px, grid 305px+975px, cards 480x470
   ============================================================ */

.section {
  background-color: transparent;
  padding: 0 3% 60px;
  display: block;
  position: relative;
}

.container {
  max-width: 1300px;
  margin-left: auto;
  margin-right: auto;
}

/* ---------- Filter header bar (search + tags) ---------- */
/* Live: grid-template-columns: 305px 955px 0px — sort is hidden */
