.filterHeader {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  background-color: transparent;
  border: none;
  border-radius: 10px;
  display: grid;
  grid-template-columns: minmax(260px, 260px) 1fr;
  align-items: center;
  min-height: 4.5rem;
  padding: 0.5rem 0 2rem;
}

/* Live: font-size 1rem, padding 1rem 1.5rem 1rem 1rem */
.searchField {
  font-family: 'Roobert PRO', Arial, sans-serif;
